    </div></div></div><div class="col-lg-7"><div class="card mb-3"><div class="card-header fw-semibold">Doctors</div><div class="table-responsive"><table class="table mb-0"><tr v-for="d in doctors" :key="d.id"><td>{{d.name}}</td><td>{{d.specialty||'—'}}</td><td>{{d.license_no||'—'}}</td></tr></table></div></div><div class="card mb-3"><div class="card-header fw-semibold">Clinics</div><div class="table-responsive"><table class="table mb-0"><tr v-for="c in clinics" :key="c.id"><td>{{c.name}}</td><td>{{c.phone}}</td><td>{{c.address}}</td></tr></table></div></div><div class="card"><div class="card-header fw-semibold">Doctor referrals</div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Reference</th><th>Doctor</th><th>Clinic</th><th>Date</th></tr></thead><tbody><tr v-for="r in referrals" :key="r.id"><td>{{r.reference_no}}</td><td>{{r.doctor?.name}}</td><td>{{r.clinic?.name||'—'}}</td><td>{{r.referred_at}}</td></tr></tbody></table></div></div></div></div>
