    </form></div></div></div><div class="col-lg-7"><div class="card"><div class="card-header fw-semibold">Scheme profitability</div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Scheme</th><th>Paid</th><th>Free</th><th>Estimated savings</th></tr></thead><tbody><tr v-for="s in schemeProfit" :key="s.id"><td>{{s.name}}</td><td>{{s.paid_quantity}}</td><td>{{s.free_quantity}}</td><td>{{money(s.estimated_saving)}}</td></tr></tbody></table></div></div></div></div>
