    <div class="card mb-3"><div class="card-header fw-semibold">Eligible near-expiry batches (select a row to populate the claim form)</div><div class="table-responsive"><table class="table table-sm mb-0"><thead><tr><th>Batch ID</th><th>Medicine</th><th>Batch</th><th>Qty</th><th>Expiry</th><th>Supplier ID</th><th></th></tr></thead><tbody><tr v-for="b in eligibleBatches" :key="b.id"><td>{{b.id}}</td><td>{{b.medicine_name}}</td><td>{{b.batch_no}}</td><td>{{b.quantity}}</td><td>{{b.expiry_date}}</td><td>{{b.supplier_id}}</td><td><button class="btn btn-sm btn-outline-primary" @click="expiry.batch_id=b.id;expiry.supplier_id=b.supplier_id;expiry.quantity=Math.max(1,Number(b.quantity))">Select</button></td></tr></tbody></table></div></div>
    <div class="card"><div class="card-header fw-semibold">Expiry claims</div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Claim</th><th>Supplier</th><th>Requested</th><th>Status</th><th>Action</th></tr></thead><tbody><tr v-for="c in expiryClaims" :key="c.id"><td>{{c.claim_no}}</td><td>{{c.supplier?.name}}</td><td>{{money(c.requested_amount)}}<div v-if="c.credit_note" class="small text-success">{{c.credit_note.credit_note_no}}</div></td><td><span class="badge text-bg-secondary">{{c.status}}</span></td><td><button v-if="c.status==='draft'" class="btn btn-sm btn-outline-primary" @click="claimAction(c,'submit')">Submit</button><button v-if="c.status==='submitted'" class="btn btn-sm btn-outline-primary" @click="reviewExpiry(c)">Approve</button><button v-if="c.status==='approved'" class="btn btn-sm btn-outline-primary ms-1" @click="claimAction(c,'credit')">Issue credit note</button></td></tr></tbody></table></div></div>
  </section>

  <section v-else-if="tab==='insurance'">
    <div class="row g-3"><div class="col-lg-4"><div class="card"><div class="card-header fw-semibold">Insurance provider</div><div class="card-body"><form @submit.prevent="saveProvider"><input v-model="provider.name" class="form-control mb-2" placeholder="Provider name" required><input v-model="provider.code" class="form-control mb-2" placeholder="Provider code" required><input v-model="provider.phone" class="form-control mb-2" placeholder="Phone"><input v-model="provider.claims_email" class="form-control mb-2" placeholder="Claims email"><button class="btn btn-primary btn-sm">Save provider</button></form><hr><div v-for="p in providers" :key="p.id" class="py-1 border-bottom">{{p.name}} <small class="text-muted">({{p.code}})</small></div>
      <hr><h6>Insurance plan</h6><form @submit.prevent="savePlan"><select v-model="plan.provider_id" class="form-select mb-2" required><option value="">Provider</option><option v-for="p in providers" :value="p.id">{{p.name}}</option></select><input v-model="plan.name" class="form-control mb-2" placeholder="Plan name" required><input v-model.number="plan.default_coverage_percent" type="number" min="0" max="100" class="form-control mb-2" placeholder="Default coverage %" required><input v-model.number="plan.annual_limit" type="number" min="0" class="form-control mb-2" placeholder="Annual limit (optional)"><button class="btn btn-outline-primary btn-sm">Save plan</button></form>
      <hr><h6>Medicine coverage rule</h6><form @submit.prevent="saveCoverage"><select v-model="coverage.plan_id" class="form-select mb-2" required><option value="">Select plan</option><option v-for="pl in allPlans" :value="pl.id">{{pl.name}} (#{{pl.id}})</option></select><select v-model="coverage.medicine_id" class="form-select mb-2"><option value="">All medicines</option><option v-for="m in medicines" :value="m.id">{{m.name}}</option></select><input v-model.number="coverage.coverage_percent" type="number" min="0" max="100" class="form-control mb-2" placeholder="Coverage %" required><input v-model.number="coverage.max_amount" type="number" min="0" class="form-control mb-2" placeholder="Maximum per medicine line (optional)"><div class="form-check mb-2"><input v-model="coverage.is_covered" type="checkbox" class="form-check-input" id="coverageEnabled"><label for="coverageEnabled" class="form-check-label">Medicine is covered</label></div><button class="btn btn-outline-primary btn-sm">Save coverage</button></form></div></div></div>
    <div class="col-lg-8"><div class="card"><div class="card-header fw-semibold">Create claim from sale</div><div class="card-body"><form @submit.prevent="createInsuranceClaim" class="row g-2"><div class="col-md-3"><EntityPicker v-model="insurance.sale_id" type="sale" placeholder="Invoice" /></div><div class="col-md-4"><select v-model="insurance.provider_id" class="form-select" required><option value="">Provider</option><option v-for="p in providers" :value="p.id">{{p.name}}</option></select></div><div class="col-md-3"><select v-model="insurance.plan_id" class="form-select" required><option value="">Select plan</option><option v-for="pl in allPlans" :value="pl.id">{{pl.name}}</option></select></div><div class="col-md-2"><button class="btn btn-primary">Create</button></div></form></div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Claim</th><th>Provider</th><th>Covered</th><th>Settled</th><th>Status</th></tr></thead><tbody><tr v-for="c in insuranceClaims" :key="c.id"><td>{{c.claim_no}}</td><td>{{c.provider?.name}}</td><td>{{money(c.covered_amount)}}</td><td>{{money(c.settled_amount)}} <small v-if="c.settlements?.length" class="text-muted">({{c.settlements.length}})</small></td><td>{{c.status}} <button v-if="c.status==='draft'" class="btn btn-sm btn-outline-primary ms-1" @click="insuranceAction(c,'submit')">Submit</button><button v-if="c.status==='submitted'" class="btn btn-sm btn-outline-primary ms-1" @click="insuranceAction(c,'review')">Approve</button><button v-if="['approved','partially_settled'].includes(c.status)" class="btn btn-sm btn-outline-primary ms-1" @click="settleInsurance(c)">Settle</button></td></tr></tbody></table></div></div></div></div>
  </section>

  <section v-else-if="tab==='analytics'">
    <div class="d-flex justify-content-between align-items-center mb-3"><div class="text-muted small">Branch-specific forecast based on recent sales history.</div><select v-model="days" class="form-select form-select-sm" style="width:150px" @change="loadAnalytics"><option :value="90">Last 90 days</option><option :value="180">Last 180 days</option><option :value="365">Last 365 days</option></select></div>
    <div class="row g-3 mb-3"><div class="col-md-3"><div class="card"><div class="card-body"><div class="text-muted small">Revenue</div><div class="fs-4 fw-semibold">{{money(analytics.profit?.revenue)}}</div></div></div></div><div class="col-md-3"><div class="card"><div class="card-body"><div class="text-muted small">Gross profit</div><div class="fs-4 fw-semibold">{{money(analytics.profit?.gross_profit)}}</div></div></div></div><div class="col-md-3"><div class="card"><div class="card-body"><div class="text-muted small">Gross margin</div><div class="fs-4 fw-semibold">{{analytics.profit?.margin_percent||0}}%</div></div></div></div><div class="col-md-3"><div class="card"><div class="card-body"><div class="text-muted small">30-day revenue forecast</div><div class="fs-4 fw-semibold">{{money(analytics.forecast?.next_30_day_revenue)}}</div></div></div></div><div class="col-md-3"><div class="card"><div class="card-body"><div class="text-muted small">30-day gross profit forecast</div><div class="fs-4 fw-semibold">{{money(analytics.forecast?.next_30_day_gross_profit)}}</div></div></div></div></div>
    <div class="card"><div class="card-header fw-semibold">Suggested purchase plan · next 30 days</div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Medicine</th><th>Current stock</th><th>Incoming</th><th>Daily demand</th><th>Order units / packs</th></tr></thead><tbody><tr v-for="m in analytics.purchase_plan||[]" :key="m.medicine_id"><td>{{m.name}}</td><td>{{m.stock}}</td><td>{{m.incoming}}</td><td>{{m.avg_daily_demand}}</td><td class="fw-semibold">{{m.suggested_order}} units / {{m.suggested_packs}} packs</td></tr></tbody></table></div></div>
    <div class="row g-3 mt-1"><div class="col-lg-6"><div class="card h-100"><div class="card-header fw-semibold">Seasonality · average revenue by month</div><div class="table-responsive"><table class="table table-sm mb-0"><thead><tr><th>Month</th><th>Avg revenue</th><th>Invoices</th></tr></thead><tbody><tr v-for="m in analytics.seasonality||[]" :key="m.month_no"><td>{{monthName(m.month_no)}}</td><td>{{money(m.avg_revenue)}}</td><td>{{m.invoices}}</td></tr></tbody></table></div></div></div><div class="col-lg-6"><div class="card h-100"><div class="card-header fw-semibold">Top medicines by units sold</div><div class="table-responsive"><table class="table table-sm mb-0"><thead><tr><th>Medicine</th><th>Units</th><th>Revenue</th></tr></thead><tbody><tr v-for="m in analytics.top_medicines||[]" :key="m.medicine_id"><td>{{m.medicine_name}}</td><td>{{m.units}}</td><td>{{money(m.revenue)}}</td></tr></tbody></table></div></div></div></div>
  </section>

  <section v-else-if="tab==='ai'">
    <div class="card"><div class="card-header fw-semibold"><i class="bi bi-stars me-2"></i>MediStore AI Assistant · Read-only</div><div class="card-body"><div class="alert alert-info small">Ask about your authorized branch's sales, low stock, expiring batches, outstanding dues and purchase orders. AI cannot modify records or provide medical advice.</div><div class="d-flex flex-wrap gap-2 mb-3"><button v-for="q in suggestions" class="btn btn-sm btn-outline-secondary" @click="question=q">{{q}}</button></div><textarea v-model="question" class="form-control mb-2" rows="3" placeholder="Ask a business question..."></textarea><button class="btn btn-primary" :disabled="busy || !question.trim()" @click="ask"><span v-if="busy" class="spinner-border spinner-border-sm me-2"></span>Ask assistant</button><div v-if="answer" class="border rounded p-3 mt-3" style="white-space:pre-wrap">{{answer}}</div></div></div>
  </section>
</div>
</template>

<script setup>
import EntityPicker from '../components/EntityPicker.vue';
import { ref, onMounted, computed } from 'vue';
import { useRoute } from 'vue-router';
import api from '../api';
import { useAuth } from '../stores/auth';

const auth=useAuth(), route=useRoute();
const tabs=[...(auth.isAdmin?[{id:'chain',label:'Branch Performance'}]:[]),{id:'doctors',label:'Doctors & Clinics'},{id:'schemes',label:'Manufacturer Schemes'},{id:'expiry',label:'Expiry Claims to Supplier'},{id:'insurance',label:'Insurance Claims'},{id:'analytics',label:'Sales Forecast'},{id:'ai',label:'AI Assistant'}];
const tabHints={chain:'Sales, purchases, expenses and stock for every branch.',doctors:'Register doctors, clinics and referrals.',schemes:'Buy-X-get-Y and discount schemes from manufacturers.',expiry:'Claim near-expiry stock back from suppliers.',insurance:'Insurance providers, plans and claims.',analytics:'Profit, seasonality and a suggested purchase plan.',ai:'Ask questions about your branch data.'};
const tab=ref(tabs.some(t=>t.id===route.query.tab)?route.query.tab:tabs[0].id),busy=ref(false),days=ref(180);
const chain=ref(null),doctors=ref([]),clinics=ref([]),referrals=ref([]),manufacturers=ref([]),medicines=ref([]),suppliers=ref([]),schemeProfit=ref([]),expiryClaims=ref([]),eligibleBatches=ref([]),providers=ref([]),insuranceClaims=ref([]),analytics=ref({}),question=ref(''),answer=ref('');
const doctor=ref({name:'',license_no:'',specialty:'',phone:'',clinic_ids:[]}),clinic=ref({name:'',phone:'',address:'',doctor_ids:[]}),referral=ref({doctor_id:'',clinic_id:'',customer_id:'',sale_id:'',referred_at:new Date().toISOString().slice(0,10),notes:''}),prescriptionLink=ref({prescription_id:'',doctor_id:'',clinic_id:''});
const scheme=ref({name:'',manufacturer_id:'',supplier_id:'',medicine_id:'',scheme_type:'buy_x_get_y',buy_quantity:10,free_quantity:2,discount_percent:0,valid_from:new Date().toISOString().slice(0,10),valid_to:new Date(Date.now()+30*86400000).toISOString().slice(0,10)});
const expiry=ref({supplier_id:'',batch_id:'',quantity:1,notes:''}),provider=ref({name:'',code:'',phone:'',claims_email:''}),insurance=ref({sale_id:'',provider_id:'',plan_id:''}),plan=ref({provider_id:'',name:'',default_coverage_percent:80,annual_limit:null}),coverage=ref({plan_id:'',medicine_id:'',coverage_percent:80,max_amount:null,is_covered:true});
const allPlans = computed(() => providers.value.flatMap(p => p.plans || []));
const suggestions=['Which medicines are low in stock?','What are my sales for the last 30 days?','Which batches expire in the next 90 days?','How much customer balance is outstanding?'];
const monthName=n=>new Date(2000,Number(n)-1,1).toLocaleString('en',{month:'long'});
const money=v=>new Intl.NumberFormat('en-PK',{style:'currency',currency:'PKR',maximumFractionDigits:0}).format(Number(v||0));
const fmt=v=>typeof v==='number'?new Intl.NumberFormat().format(v):v;
async function get(url){const {data}=await api.get(url);return data?.data??data;}
async function refresh(){await loadTab();}
async function loadTab(){
 try{
  if(tab.value==='chain') chain.value=await get('/stage4/chain/overview');
  if(tab.value==='doctors'){const [d,c,l,rf]=await Promise.all([get('/stage4/doctors'),get('/stage4/clinics'),get('/stage4/lookups'),get('/stage4/referrals')]);doctors.value=d.data||d;clinics.value=c.data||c;referrals.value=rf.data||rf;manufacturers.value=l.manufacturers||[];suppliers.value=l.suppliers||[];medicines.value=l.medicines||[];}
  if(tab.value==='schemes'){const [s,l]=await Promise.all([get('/stage4/schemes/profitability'),get('/stage4/lookups')]);schemeProfit.value=s;manufacturers.value=l.manufacturers||[];medicines.value=l.medicines||[];suppliers.value=l.suppliers||[];}
  if(tab.value==='expiry'){const [c,l]=await Promise.all([get('/stage4/expiry-claims'),get('/stage4/lookups')]);expiryClaims.value=c.data||c;suppliers.value=l.suppliers||[];eligibleBatches.value=l.expiring_batches||[];}
  if(tab.value==='insurance'){const [p,c,l]=await Promise.all([get('/stage4/insurance-providers'),get('/stage4/insurance-claims'),get('/stage4/lookups')]);providers.value=p.data||p;insuranceClaims.value=c.data||c;medicines.value=l.medicines||[];}
  if(tab.value==='analytics') await loadAnalytics();
 }catch(e){console.error(e);}
}
async function loadAnalytics(){analytics.value=await get(`/stage4/analytics?days=${days.value}`);}
async function saveDoctor(){await api.post('/stage4/doctors',doctor.value);doctor.value={name:'',license_no:'',specialty:'',phone:'',clinic_ids:[]};await loadTab();}
async function saveClinic(){await api.post('/stage4/clinics',clinic.value);clinic.value={name:'',phone:'',address:'',doctor_ids:[]};await loadTab();}
async function saveReferral(){await api.post('/stage4/referrals',referral.value);referral.value={doctor_id:'',clinic_id:'',customer_id:'',sale_id:'',referred_at:new Date().toISOString().slice(0,10),notes:''};await loadTab();}
async function linkPrescription(){const {prescription_id,...payload}=prescriptionLink.value;await api.patch(`/stage4/prescriptions/${prescription_id}/doctor`,payload);prescriptionLink.value={prescription_id:'',doctor_id:'',clinic_id:''};}
async function saveScheme(){await api.post('/stage4/schemes',scheme.value);await loadTab();}
async function createExpiry(){await api.post('/stage4/expiry-claims',{supplier_id:expiry.value.supplier_id,notes:expiry.value.notes,items:[{batch_id:expiry.value.batch_id,quantity:expiry.value.quantity}]});expiry.value={supplier_id:'',batch_id:'',quantity:1,notes:''};await loadTab();}
async function claimAction(c,action){await api.post(`/stage4/expiry-claims/${c.id}/${action}`);await loadTab();}
async function reviewExpiry(c){await api.post(`/stage4/expiry-claims/${c.id}/review`,{decision:'approved'});await loadTab();}
async function saveProvider(){await api.post('/stage4/insurance-providers',provider.value);provider.value={name:'',code:'',phone:'',claims_email:''};await loadTab();}
async function savePlan(){await api.post('/stage4/insurance-plans',plan.value);plan.value={provider_id:'',name:'',default_coverage_percent:80,annual_limit:null};await loadTab();}
async function saveCoverage(){await api.post('/stage4/insurance-coverages',coverage.value);coverage.value={plan_id:'',medicine_id:'',coverage_percent:80,max_amount:null,is_covered:true};}
async function createInsuranceClaim(){await api.post('/stage4/insurance-claims',insurance.value);insurance.value={sale_id:'',provider_id:'',plan_id:''};await loadTab();}
async function insuranceAction(c,action){if(action==='review')await api.post(`/stage4/insurance-claims/${c.id}/review`,{decision:'approved'});else await api.post(`/stage4/insurance-claims/${c.id}/submit`);await loadTab();}
async function settleInsurance(c){const amount=Number(prompt(`Enter settlement amount (outstanding ${Number(c.covered_amount)-Number(c.settled_amount)})`));if(!amount||amount<=0)return;await api.post(`/stage4/insurance-claims/${c.id}/settle`,{amount});await loadTab();}
async function ask(){busy.value=true;answer.value='';try{const {data}=await api.post('/stage4/ai/ask',{question:question.value});answer.value=data.answer;}finally{busy.value=false;}}
onMounted(loadTab);
</script>
